from sage.all_cmdline import *   # import sage library

_sage_const_300 = Integer(300); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_1000 = Integer(1000); _sage_const_0p4407 = RealNumber('0.4407'); _sage_const_0p2 = RealNumber('0.2'); _sage_const_0p813 = RealNumber('0.813'); _sage_const_0p05 = RealNumber('0.05'); _sage_const_0p1 = RealNumber('0.1'); _sage_const_0p4 = RealNumber('0.4'); _sage_const_0p8 = RealNumber('0.8'); _sage_const_1p2 = RealNumber('1.2'); _sage_const_0p3 = RealNumber('0.3'); _sage_const_1p7 = RealNumber('1.7'); _sage_const_5p0 = RealNumber('5.0'); _sage_const_10p4 = RealNumber('10.4'); _sage_const_20 = Integer(20); _sage_const_30 = Integer(30)# ---------------------------------------------------------
# <cosh_sinh_basic_properties> (1)
#   cosh x - sinh x = exp(-x) > 0,  cosh x + sinh x = exp(x) > 0
#   特に cosh x > 0 かつ cosh x > sinh x
#
# 独立経路: 左辺は cosh, sinh の**定義式**
#   cosh x = (exp(x)+exp(-x))/2, sinh x = (exp(x)-exp(-x))/2
# を 300 bit の実数演算で組み上げたもの。右辺は exp(-x), exp(x) をそのまま評価したもの。
# 「定義から exp へ戻る」という主張そのものを、両辺別々に数値評価して突き合わせる。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

RF = RealField(_sage_const_300 )

def cosh_def(x):
    return (RF(x).exp() + RF(-x).exp()) / _sage_const_2 

def sinh_def(x):
    return (RF(x).exp() - RF(-x).exp()) / _sage_const_2 

# 臨界点まわりの結合定数（2 K_1 の形で現れる）も含めて広く取る
XS = [RF(v) for v in [
    _sage_const_0 , _sage_const_1 /_sage_const_1000 , -_sage_const_1 /_sage_const_1000 , _sage_const_1 /_sage_const_2 , -_sage_const_1 /_sage_const_2 , _sage_const_1 , -_sage_const_1 , _sage_const_2 , -_sage_const_2 ,
    _sage_const_2 *_sage_const_0p4407 , -_sage_const_2 *_sage_const_0p4407 , _sage_const_2 *_sage_const_0p2 , _sage_const_2 *_sage_const_0p813 , _sage_const_2 *_sage_const_0p05 , _sage_const_2 *_sage_const_0p1 ,
    _sage_const_2 *_sage_const_0p4 , _sage_const_2 *_sage_const_0p8 , _sage_const_2 *_sage_const_1p2 , _sage_const_2 *_sage_const_0p3 , _sage_const_2 *_sage_const_1p7 , _sage_const_2 *_sage_const_5p0 , _sage_const_2 *_sage_const_10p4 , -_sage_const_2 *_sage_const_10p4 ,
    _sage_const_20 , -_sage_const_20 , _sage_const_30 , -_sage_const_30 ,
]]

rep = CheckReport("<cosh_sinh_basic_properties> (1) cosh-sinh=exp(-x), cosh+sinh=exp(x)")

for x in XS:
    c = cosh_def(x)
    s = sinh_def(x)
    rep.close(float(c - s), float(RF(-x).exp()), "cosh-sinh=exp(-x) @x=%s" % x)
    rep.close(float(c + s), float(RF(x).exp()), "cosh+sinh=exp(x) @x=%s" % x)
    rep.truth(RF(-x).exp() > _sage_const_0 , "exp(-x)>0 @x=%s" % x)
    rep.truth(RF(x).exp() > _sage_const_0 , "exp(x)>0 @x=%s" % x)
    rep.truth(c > _sage_const_0 , "cosh>0 @x=%s" % x)
    rep.truth(c > s, "cosh>sinh @x=%s" % x)

rep.finish()

